/*
 * NOVA_ATELIER — Data Ticker Ribbon
 * 1. COMPOSITION: a thin 7.0x0.35 instrumentation rail centered at origin, framed by a
 *    faint ink-colored bezel and a graded near-black atmospheric backdrop (anti-void) behind it.
 * 2. LIGHT RIG: scene supplies ambient 0.6 + key 1.2; locally we add a soft white rim
 *    (behind, low intensity) and a warm accent point light to catch the red tick marks.
 * 3. MATERIALS: MeshStandardNodeMaterial for the rail/hairlines/ticks (roughness 0.6,
 *    metalness 0.2, emissive accent on ticks); MeshBasicNodeMaterial + TSL alpha ramp for
 *    the edge-fade overlay so figures dissolve rather than clip.
 * 4. MOTION: a duplicated content strip translated linearly (ease:none) at 0.4 units/sec,
 *    looping with zero visible seam; fly-through primitive applied per contract (depthUnits 0).
 * 5. FOCAL ELEMENT: none of the ticker figures individually dominate — the accent tick marks
 *    read as the single graded highlight against the otherwise quiet mono-paper text.
 */

import {
  Group,
  Mesh,
  PlaneGeometry,
  BoxGeometry,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  DirectionalLight,
  PointLight,
  Box3,
} from 'three/webgpu';
import { uv, smoothstep, oneMinus, max as tslMax, color as tslColor } from 'three/tsl';
import { gsap } from 'gsap';

const BG = '#0b0b10';
const SURFACE = '#111117';
const INK = '#16161d';
const PAPER = '#e8ecf2';
const ACCENT = '#ff2a38';
const HAIRLINE = '#23232b';

function disposeObject3D(obj) {
  if (!obj) return;
  obj.traverse((child) => {
    if (child.geometry) child.geometry.dispose();
    if (child.material) {
      const mats = Array.isArray(child.material) ? child.material : [child.material];
      for (const m of mats) {
        if (!m) continue;
        for (const key of ['map', 'emissiveMap', 'roughnessMap', 'metalnessMap', 'normalMap']) {
          if (m[key] && m[key].dispose) m[key].dispose();
        }
        m.dispose();
      }
    }
  });
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();
  root.name = 'ticker-ribbon';

  const RIBBON_W = 7.0;
  const RIBBON_H = 0.35;

  // ---- 1. atmospheric backdrop (anti-void) ----------------------------------
  const backdropGeo = new PlaneGeometry(7.0, 6.0);
  const backdropMat = new MeshStandardNodeMaterial({
    roughness: 0.9,
    metalness: 0.0,
  });
  {
    const uvNode = uv();
    const grad = uvNode.y.mul(0.35).add(tslColor(SURFACE).mul(0)); // placeholder to keep node graph simple
    // vertical mix between background (edges) and surface (center) for a graded, non-flat stage
    const midMask = smoothstep(0.15, 0.5, uvNode.y).mul(oneMinus(smoothstep(0.5, 0.85, uvNode.y)));
    backdropMat.colorNode = tslColor(BG).mix(tslColor(SURFACE), midMask.mul(0.6));
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---- 2. ink bezel frame around the rail -----------------------------------
  const bezelGeo = new PlaneGeometry(RIBBON_W + 0.1, RIBBON_H + 0.1);
  const bezelMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(INK),
    roughness: 0.7,
    metalness: 0.15,
  });
  const bezel = new Mesh(bezelGeo, bezelMat);
  bezel.position.set(0, 0, -0.01);
  root.add(bezel);

  // ---- 3. the ribbon rail surface --------------------------------------------
  const railGeo = new PlaneGeometry(RIBBON_W, RIBBON_H);
  const railMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(SURFACE),
    roughness: 0.6,
    metalness: 0.2,
  });
  const rail = new Mesh(railGeo, railMat);
  rail.position.set(0, 0, 0);
  root.add(rail);

  // ---- hairlines --------------------------------------------------------------
  const hairlineGeo = new PlaneGeometry(RIBBON_W, 0.006);
  const hairlineMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(HAIRLINE),
    roughness: 0.6,
    metalness: 0.2,
  });
  const hairlineTop = new Mesh(hairlineGeo, hairlineMat);
  hairlineTop.position.set(0, RIBBON_H / 2 - 0.003, 0.001);
  const hairlineBottom = new Mesh(hairlineGeo, hairlineMat.clone());
  hairlineBottom.position.set(0, -RIBBON_H / 2 + 0.003, 0.001);
  root.add(hairlineTop, hairlineBottom);

  // ---- 4. content strip: text figures + accent tick marks --------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const GAP = 0.5; // 2x base unit
  const TICK_W = 0.02;
  const TICK_H = 0.14;

  const tickMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(INK),
    emissive: new THREE.Color(ACCENT),
    emissiveIntensity: 1.5,
    roughness: 0.5,
    metalness: 0.3,
  });

  const stripSourceGroup = new Group();
  const textMeshes = [];
  const tickMeshes = [];
  let cursorX = 0;

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const typo = item.typography ?? { fontSize: 13, letterSpacing: 0.06 };
    const fontSize = typo.fontSize ?? 13;
    const letterSpacingPx = (typo.letterSpacing ?? 0.06) * fontSize;

    const textMesh = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize,
      color: PAPER,
      align: 'left',
      letterSpacingPx,
    });
    textMesh.position.set(cursorX, 0, 0.02);
    stripSourceGroup.add(textMesh);
    textMeshes.push(textMesh);

    const box = new Box3().setFromObject(textMesh);
    const width = Math.max(box.max.x - box.min.x, fontSize * 0.02 * (item.text?.length ?? 1));
    cursorX += width;

    // tick mark with gaps on both sides (also placed after the final item to
    // keep rhythm uniform across the seamless loop boundary)
    cursorX += GAP;
    const tick = new Mesh(new BoxGeometry(TICK_W, TICK_H, 0.01), tickMat);
    tick.position.set(cursorX + TICK_W / 2, 0, 0.02);
    stripSourceGroup.add(tick);
    tickMeshes.push(tick);
    cursorX += TICK_W;
    cursorX += GAP;
  }

  const stripWidth = cursorX;

  const stripCopyA = stripSourceGroup;
  const stripCopyB = stripSourceGroup.clone(true);
  stripCopyB.position.x = stripWidth;

  const scrollContainer = new Group();
  scrollContainer.add(stripCopyA, stripCopyB);
  scrollContainer.position.set(-RIBBON_W / 2 + 0.1, 0, 0);
  root.add(scrollContainer);

  // ---- 5. edge fade overlay (TSL alpha ramp, the 4-stop gradient) ------------
  const fadeGeo = new PlaneGeometry(RIBBON_W, RIBBON_H);
  const fadeMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  {
    const uvNode = uv();
    const leftMask = oneMinus(smoothstep(0.0, 0.09, uvNode.x));
    const rightMask = smoothstep(0.91, 1.0, uvNode.x);
    const alphaNode = tslMax(leftMask, rightMask);
    fadeMat.colorNode = tslColor(BG);
    fadeMat.opacityNode = alphaNode;
  }
  const fadeOverlay = new Mesh(fadeGeo, fadeMat);
  fadeOverlay.position.set(0, 0, 0.03);
  root.add(fadeOverlay);

  // ---- lighting: node-local rim + accent catch light --------------------------
  const rimLight = new DirectionalLight(0xffffff, 0.9);
  rimLight.position.set(0, 0.6, -2);
  rimLight.target.position.set(0, 0, 0);
  root.add(rimLight, rimLight.target);

  const accentLight = new PointLight(new THREE.Color(ACCENT), 0.7, 4);
  accentLight.position.set(0, 0.1, 0.6);
  root.add(accentLight);

  // ---- primitive: fly-through (required by contract) --------------------------
  const flyThrough = ctx.primitives['fly-through'](scrollContainer, {
    depthUnits: 0,
    speed: 0.4,
  });

  // ---- manual constant-velocity linear scroll with seamless wrap ---------------
  const duration = stripWidth / 0.4;
  const scrollTween = gsap.to(scrollContainer.position, {
    x: scrollContainer.position.x - stripWidth,
    duration,
    ease: 'none',
    repeat: -1,
  });

  // ---- weighted-settle entrance -------------------------------------------------
  root.scale.set(0.98, 0.98, 0.98);
  const entranceTween = gsap.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    scrollTween.kill();
    entranceTween.kill();
    if (flyThrough && typeof flyThrough.cleanup === 'function') flyThrough.cleanup();
    disposeObject3D(backdrop);
    disposeObject3D(bezel);
    disposeObject3D(rail);
    disposeObject3D(hairlineTop);
    disposeObject3D(hairlineBottom);
    disposeObject3D(fadeOverlay);
    disposeObject3D(stripCopyA);
    disposeObject3D(stripCopyB);
    tickMat.dispose();
    root.remove(rimLight, rimLight.target, accentLight);
  };

  return root;
}

/* @spec-manifest
{"elements":[
  {"id":"text.ticker-figure.0","where":"createNode/content-strip-loop","how":"first item text rendered via ctx.fontAtlas.createText"},
  {"id":"text.ticker-figure.1","where":"createNode/content-strip-loop","how":"second item text rendered via ctx.fontAtlas.createText"},
  {"id":"text.ticker-figure.2","where":"createNode/content-strip-loop","how":"third item text rendered via ctx.fontAtlas.createText"},
  {"id":"text.ticker-figure.3","where":"createNode/content-strip-loop","how":"fourth item text rendered via ctx.fontAtlas.createText"},
  {"id":"text.ticker-figure.4","where":"createNode/content-strip-loop","how":"fifth item text rendered via ctx.fontAtlas.createText"},
  {"id":"text.ticker-figure.5","where":"createNode/content-strip-loop","how":"sixth item text rendered via ctx.fontAtlas.createText"},
  {"id":"color.background","where":"createNode/backdropMat+fadeMat","how":"BG used in backdrop gradient and edge-fade overlay colorNode"},
  {"id":"color.surface","where":"createNode/railMat+backdropMat","how":"SURFACE used for rail material and backdrop mid color"},
  {"id":"color.ink","where":"createNode/bezelMat+tickMat","how":"INK used for bezel plane and tick base color"},
  {"id":"color.paper","where":"createNode/content-strip-loop","how":"PAPER passed as text color to ctx.fontAtlas.createText"},
  {"id":"color.accent","where":"createNode/tickMat+accentLight","how":"ACCENT used as tick emissive and accent point light"},
  {"id":"color.gradient","where":"createNode/fadeMat-TSL-alpha","how":"4-stop 0/0.09/0.91/1 ramp built with smoothstep+oneMinus+max"},
  {"id":"effects.spec","where":"createNode/rail+hairlines+ticks+fadeOverlay","how":"rail dims, hairlines, ticks, float z, edge fade all built"},
  {"id":"primitive.fly-through","where":"createNode/flyThrough call","how":"ctx.primitives['fly-through'] applied to scrollContainer"}
]}
*/
